        Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);
        Vector128<byte> lut = Vector128.Create(
            (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                  0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;

        if (Avx2.IsSupported)
        {
            Vector256<byte> lowNibbleMask256 = Vector256.Create((byte)0x0F);
            Vector256<byte> lut256 = Vector256.Create(
                (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                      0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F,
                      0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                      0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

            int limit256 = data.Length - Vector256<byte>.Count + 1;
            for (; i < limit256; i += Vector256<byte>.Count)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                Vector256<byte> vec = Unsafe.As<byte, Vector256<byte>>(ref src);

                Vector256<byte> lo = Avx2.And(vec, lowNibbleMask256);
                Vector256<byte> hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), lowNibbleMask256);

                // Reverse low nibble bits → becomes high nibble of result
                Vector256<byte> reversedLo = Avx2.Shuffle(lut256, lo);
                // Reverse high nibble bits → becomes low nibble of result
                Vector256<byte> reversedHi = Avx2.Shuffle(lut256, hi);

                Vector256<byte> result = Avx2.Or(Avx2.ShiftLeftLogical(reversedLo.AsInt16(), 4).AsByte(), reversedHi);
                Unsafe.As<byte, Vector256<byte>>(ref src) = result;
            }
        }

        int limit128 = data.Length - Vector128<byte>.Count + 1;
        for (; i < limit128; i += Vector128<byte>.Count)
        {
            ref byte src = ref Unsafe.Add(ref ptr, i);
            Vector128<byte> vec = Unsafe.As<byte, Vector128<byte>>(ref src);

            Vector128<byte> lo = Sse2.And(vec, lowNibbleMask);
            Vector128<byte> hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsInt16(), 4).AsByte(), lowNibbleMask);

            Vector128<byte> reversedLo = Ssse3.Shuffle(lut, lo);
            Vector128<byte> reversedHi = Ssse3.Shuffle(lut, hi);

            Vector128<byte> result = Sse2.Or(Sse2.ShiftLeftLogical(reversedLo.AsInt16(), 4).AsByte(), reversedHi);
            Unsafe.As<byte, Vector128<byte>>(ref src) = result;
        }

        // Scalar tail
        ReadOnlySpan<byte> table = LookupTable;
        for (; i < data.Length; i++)
        {
            data[i] = table[data[i]];
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseInPlaceNeon(Span<byte> data)
    {
        // ARM NEON: RBIT reverses all bits in a 32-bit element; combine with REV to get per-byte reversal
        // Alternatively use the same VTBL nibble-lookup approach
        Vector128<byte> lowNibbleMask = Vector128.Create((byte)0x0F);
        Vector128<byte> lut = Vector128.Create(
            (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                  0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int limit = data.Length - Vector128<byte>.Count + 1;

        for (; i < limit; i += Vector128<byte>.Count)
        {
            ref byte src = ref Unsafe.Add(ref ptr, i);
            Vector128<byte> vec = Unsafe.As<byte, Vector128<byte>>(ref src);

            Vector128<byte> lo = AdvSimd.And(vec, lowNibbleMask);
            Vector128<byte> hi = AdvSimd.And(AdvSimd.ShiftRightLogical(vec, 4), lowNibbleMask);

            Vector128<byte> reversedLo = AdvSimd.Arm64.VectorTableLookup(lut, lo);
            Vector128<byte> reversedHi = AdvSimd.Arm64.VectorTableLookup(lut, hi);

            Vector128<byte> result = AdvSimd.Or(AdvSimd.ShiftLeftLogical(reversedLo, 4), reversedHi);
            Unsafe.As<byte, Vector128<byte>>(ref src) = result;
        }

        ReadOnlySpan<byte> table = LookupTable;
        for (; i < data.Length; i++)
        {
            data[i] = table[data[i]];
        }
    }

    private static void ReverseInPlaceScalar(Span<byte> data)
    {
        ReadOnlySpan<byte> table = LookupTable;
        for (int i = 0; i < data.Length; i++)
        {
            data[i] = table[data[i]];
        }
    }
}

